def compute(vars):
    cost = vars["v1"]
    period = vars["v2"]
    if period == 0:
        return None
    value = cost / period
    return {
        "value": value,
        "trace": {
            "cost": cost,
            "period_years": period,
            "average_cost_per_year": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "per year"
            }
        }
    }
